            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        supported_versions = {
            (3, 0): cls.Bolt30Handler,
            (3, 1): cls.Bolt31Handler,
            (3, 5): cls.Bolt35Handler,
            (4, 0): cls.Bolt40Handler,
            (4, 1): cls.Bolt41Handler,
            (4, 2): cls.Bolt42Handler,
            (4, 3): cls.Bolt43Handler,
            (4, 4): cls.Bolt44Handler,
            (5, 0): cls.Bolt50Handler,
