def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if isinstance(value, dict):
            if key in response:
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], value, response[key]
                )
            else:
                raise KeyError(f"Observed field '{key}' not present in Kubernetes response")
        elif isinstance(value, list):
            if key in response:
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = []
                for i, item in enumerate(response[key]):
                    if i < len(last_applied_manifest[key]):
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[key][i], value[0], item
                        )
                    else:
                        last_applied_manifest[key].append({})
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[key][i], value[0], item
                        )
            else:
                raise KeyError(f"Observed field '{key}' not present in Kubernetes response")
        else:
            if key in response:
                last_applied_manifest[key] = response[key]
            else:
                raise KeyError(f"Observed field '{key}' not present in Kubernetes response")
