from krake.data.kubernetes import Application

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Assuming the Application class has a 'spec' attribute with a 'manifest' attribute
    # and a 'observer_schema' attribute to store the observer schema.

    # Iterate over each resource in the manifest
    for resource in app.spec.manifest:
        # Check if a custom observer schema is already specified for this resource
        if resource.get('observer_schema') is None:
            # Generate a default observer schema for this resource
            default_schema = {
                "type": "object",
                "properties": {
                    "status": {
                        "type": "string"
                    }
                },
                "required": ["status"]
            }
            # Assign the default observer schema to the resource
            resource['observer_schema'] = default_schema

    # Update the application's observer schema with the modified manifest
    app.observer_schema = app.spec.manifest
