import os
import json

class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not os.path.exists(path):
            return False

        if not os.path.isdir(path):
            return False

        if not os.path.exists(os.path.join(path, '0=ocfl_1.0')):
            return False

        if not os.path.exists(os.path.join(path, 'inventory.json')):
            return False

        with open(os.path.join(path, 'inventory.json'), 'r') as f:
            try:
                inventory = json.load(f)
            except json.JSONDecodeError:
                return False

        if 'id' not in inventory or 'type' not in inventory or 'head' not in inventory:
            return False

        if inventory['type'] != 'https://ocfl.io/1.0/spec/#inventory':
            return False

        return True
