import hashlib

class DigestChecker:
    def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        for file_path, expected_digest in manifest_files.items():
            if file_path not in digests_used:
                raise ValueError(f"Digest for file {file_path} is not used.")

            actual_digest = self.calculate_file_digest(file_path)
            if actual_digest != expected_digest:
                raise ValueError(f"Digest mismatch for file {file_path}. Expected {expected_digest}, got {actual_digest}.")

    def calculate_file_digest(self, file_path):
        """Calculate the SHA-256 digest of a file."""
        hash_sha256 = hashlib.sha256()
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                hash_sha256.update(byte_block)
        return hash_sha256.hexdigest()

