        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Check if fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        # Check if all keys in fixity are strings
        if not all(isinstance(key, str) for key in fixity.keys()):
            raise ValueError("All keys in fixity block must be strings")

        # Check if all values in fixity are dictionaries
        if not all(isinstance(value, dict) for value in fixity.values()):
            raise ValueError("All values in fixity block must be dictionaries")

        # Check if each value dictionary has 'algorithm' and 'value' keys
        for file_hash in fixity.values():
            if 'algorithm' not in file_hash or 'value' not in file_hash:
                raise ValueError("Each file hash must have 'algorithm' and 'value' keys")

        # Check if all files in fixity are in the manifest
        for file_name in fixity.keys():
            if file_name not in manifest_files:
                raise ValueError(f"File '{file_name}' in fixity block is not listed in the manifest")

        return True

# Example usage
if __name__ == "__main__":
    validator = InventoryValidator()
    fixity = {
        "file1.txt": {"algorithm": "sha256", "value": "abc123"},
        "file2.txt": {"algorithm": "sha256", "value": "def456"}
    }
    manifest_files = ["file1.txt", "file2.txt", "file3.txt"]
    try:
        validator.validate_fixity(fixity, manifest_files)
        print("Fixity block is valid.")
    except ValueError as e:
        print(f"Validation error: {e}")
