import os
import hashlib

class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        root_inventory = self._load_inventory(version_dirs[0])
        content_digests = {}

        for version_dir in version_dirs:
            inventory = self._load_inventory(version_dir)
            for content_id, content_info in inventory.items():
                if content_id not in root_inventory or root_inventory[content_id] != content_info:
                    content_digests[content_id] = content_info

        self._validate_content_digests(content_digests)

    def _load_inventory(self, version_dir):
        inventory_path = os.path.join(version_dir, 'inventory.json')
        with open(inventory_path, 'r') as f:
            return json.load(f)

    def _validate_content_digests(self, content_digests):
        for content_id, content_info in content_digests.items():
            content_path = os.path.join(content_info['path'], content_id)
            with open(content_path, 'rb') as f:
                content_data = f.read()
                calculated_digest = hashlib.sha256(content_data).hexdigest()
                if calculated_digest != content_info['digest']:
                    raise ValueError(f"Content digest mismatch for {content_id}: expected {content_info['digest']}, got {calculated_digest}")

# Example usage:
# validator = VersionValidator()
# validator.validate_version_inventories(['version1', 'version2', 'version3'])
```

This code assumes that each version directory contains an `inventory.json` file with the following structure:
```json
{
    "content_id1": {
        "path": "path/to/content",
        "digest": "sha256_digest_of_content"
    },
    "content_id2": {
        "path": "path/to/content",
        "digest": "sha256_digest_of_content"
    }
}
```

The `validate_version_inventories` method checks that each version has an inventory and compares the content digests to those in the root inventory. If any content digest does not match, it raises a `ValueError`.

