    merged_result = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_result:
            if isinstance(merged_result[key], MappingNode) and isinstance(value_node, MappingNode):
                merged_result[key] = MappingNode(
                    tag=value_node.tag,
                    value=merge_dicts(merged_result[key].value, value_node.value)
                )
            else:
                merged_result[key] = value_node
        else:
            merged_result[key] = value_node

    return [(ScalarNode(tag=key_node.tag, value=key), value) for key, value in merged_result.items()]
