from zope.interface import Interface, implementer, Invalid, providedBy
from inspect import signature, Parameter

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not providedBy(candidate, iface):
        raise Invalid(f"{candidate} does not provide {iface}")

    missing_methods = []
    missing_attributes = []
    incorrect_signatures = []

    for name, method in iface.namesAndDescriptions():
        if not callable(getattr(candidate, name, None)):
            missing_methods.append(name)
        else:
            method_signature = signature(getattr(candidate, name))
            expected_signature = signature(method)
            if method_signature != expected_signature:
                incorrect_signatures.append((name, method_signature, expected_signature))

    for name in iface.names():
        if not hasattr(candidate, name):
            missing_attributes.append(name)

    errors = []
    if missing_methods:
        errors.append(f"Missing methods: {', '.join(missing_methods)}")
    if incorrect_signatures:
        for name, actual, expected in incorrect_signatures:
            errors.append(f"Incorrect signature for {name}: expected {expected}, got {actual}")
    if missing_attributes:
        errors.append(f"Missing attributes: {', '.join(missing_attributes)}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True
