def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        metaclass = type(base)
        metaclasses.add(metaclass)

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, try to find a common metaclass
    common_metaclass = None
    for metaclass in metaclasses:
        if issubclass(metaclass, type):
            if common_metaclass is None:
                common_metaclass = metaclass
            elif not issubclass(common_metaclass, metaclass):
                raise TypeError("Inconsistent metaclasses for bases")

    if common_metaclass is not None:
        return common_metaclass

    # Default to type if no common metaclass is found
    return type
